21	/// Interface for string parsers.
22	struct ITokenizer
23	{
24	public:
25	    enum class Type
26	    {
27	        SplitByNonAlpha,
28	        Ngrams,
29	        SplitByString,
30	        Array,
31	        SparseGrams,
32	        AsciiCJK,
33	    };
34	
35	    ITokenizer() = default;
36	    explicit ITokenizer(Type type_) : type(type_) {}
37	    ITokenizer(const ITokenizer &) = default;
38	    ITokenizer & operator=(const ITokenizer &) = default;
39	
40	    Type getType() const { return type; }
41	
42	    virtual ~ITokenizer() = default;
43	    virtual std::unique_ptr<ITokenizer> clone() const = 0;
44	
45	    /// Returns a formatted description of the tokenizer with arguments.
46	    virtual String getDescription() const = 0;
47	
48	    virtual const char * getTokenizerName() const = 0;
49	    virtual const char * getTokenizerExternalName() const = 0;
50	
51	    /// Fast inplace implementation for regular use.
52	    /// Gets string (data ptr and len) and start position for extracting next token (state of tokenizer).
53	    /// Returns false if parsing is finished, otherwise returns true.
54	    virtual bool nextInString(const char * data, size_t length, size_t & __restrict pos, size_t & __restrict token_start, size_t & __restrict token_length) const = 0;
55	
56	    /// Special implementation for creating bloom filter for LIKE function.
57	    /// It skips unescaped `%` and `_` and supports escaping symbols, but it is less lightweight.
58	    virtual bool nextInStringLike(const char * data, size_t length, size_t & pos, String & out) const = 0;
59	
60	    /// Updates Bloom filter from exact-match string filter value
61	    virtual void stringToBloomFilter(const char * data, size_t length, BloomFilter & bloom_filter) const = 0;
62	
63	    /// Filters out tokens excessive for search.
64	    /// This method is inefficient and should be used only for constants.
65	    virtual std::vector<String> compactTokens(const std::vector<String> & tokens) const = 0;
66	
67	    /// Updates Bloom filter from substring-match string filter value.
68	    /// An `ITokenizer` implementation may decide to skip certain
69	    /// tokens depending on whether the substring is a prefix or a suffix.
70	    virtual void substringToBloomFilter(
71	        const char * data,
72	        size_t length,
73	        BloomFilter & bloom_filter,
74	        bool is_prefix,
75	        bool is_suffix) const = 0;
76	
77	    virtual void stringLikeToBloomFilter(const char * data, size_t length, BloomFilter & bloom_filter) const = 0;
78	
79	    /// Collects copy of tokens into vector. This method is inefficient and should be used only for constants.
80	    virtual void stringToTokens(const char * data, size_t length, std::vector<String> & tokens) const = 0;
81	
82	    /// Collects copy of tokens into vector from substring-match string filter value.
83	    /// An `ITokenizer` implementation may decide to skip certain
84	    /// tokens depending on whether the substring is a prefix or a suffix.
85	    /// This method is inefficient and should be used only for constants.
86	    virtual void substringToTokens(
87	        const char * data,
88	        size_t length,
89	        std::vector<String> & tokens,
90	        bool is_prefix,
91	        bool is_suffix) const = 0;
92	
93	    virtual void stringLikeToTokens(const char * data, size_t length, std::vector<String> & tokens) const = 0;
94	    virtual bool supportsStringLike() const = 0;
95	
96	private:
97	    Type type;
98	};
