3	-- Tests if a text index LIKE evaluation by scanning the inverted index dictionary is properly applied.
4	
5	SET enable_analyzer = 1;
6	
7	SELECT 'Test results are same with/without the optimization';
8	
9	DROP TABLE IF EXISTS tab;
10	
11	CREATE TABLE tab
12	(
13	    id UInt32,
14	    message String,
15	    INDEX idx(message) TYPE text(tokenizer = splitByNonAlpha)
16	)
17	ENGINE = MergeTree
18	ORDER BY (id);
19	
20	INSERT INTO tab(id, message) VALUES
21	    (1, 'abc def foo'),
22	    (2, 'abc def bar'),
23	    (3, 'abc baz foo'),
24	    (4, 'abc baz bar'),
25	    (5, 'xyz');
26	
27	SET use_text_index_like_evaluation_by_dictionary_scan = 0;
28	
29	SELECT '-- without optimization';
30	
31	SELECT groupArray(id) FROM tab WHERE message LIKE '%foo%';
