463	void MergeTreeIndexGranuleText::analyzeDictionaryForPatterns(MergeTreeIndexReaderStream & header_stream, MergeTreeIndexReaderStream & dictionary_stream, MergeTreeIndexDeserializationState & state)
464	{
465	    const auto & condition_text = typeid_cast<const MergeTreeIndexConditionText &>(*state.condition);
466	    const auto & all_search_patterns = condition_text.getAllSearchPatterns();
467	
468	    if (all_search_patterns.empty())
469	    {
470	        can_use_like_dictionary_scan = true;
471	        return;
472	    }
473	
474	    auto sparse_index = loadSparseIndex(header_stream, state);
475	    if (sparse_index->empty())
476	    {
477	        can_use_like_dictionary_scan = true;
478	        return;
479	    }
480	
481	    const size_t max_postings_to_read = condition_text.getContext()->getSettingsRef()[Setting::text_index_like_max_postings_to_read];
482	
483	    size_t postings_to_read = 0;
484	    std::vector<size_t> matched_indices;
485	    for (size_t block_idx = 0; block_idx < sparse_index->size(); ++block_idx)
486	    {
487	        /// TODO(ahmadov): Include the byte size of token infos into dictionary block to avoid multi-seek.
488	        UInt64 offset_in_file = sparse_index->getOffsetInFile(block_idx);
489	        dictionary_stream.seekToMark({offset_in_file, 0});
490	        auto * data_buffer = dictionary_stream.getDataBuffer();
491	
492	        auto tokens_column = TextIndexSerialization::deserializeTokens(*data_buffer).first;
493	        const auto & block_tokens = assert_cast<const ColumnString &>(*tokens_column);
494	        size_t num_tokens = block_tokens.size();
495	
496	        matched_indices.clear();
497	
498	        for (size_t token_idx = 0; token_idx < num_tokens; ++token_idx)
499	        {
500	            const auto & token = block_tokens.getDataAt(token_idx);
501	            if (std::ranges::any_of(all_search_patterns, [&](const auto * pattern) { return pattern->match(token.data(), token.size()); }))
502	            {
503	                matched_indices.emplace_back(token_idx);
504	            }
505	        }
506	
507	        if (matched_indices.empty())
508	            continue;
509	
510	        /// Deserialize only the token infos for matched tokens.
511	        auto token_infos = TextIndexSerialization::deserializeTokenInfos(
512	            *data_buffer,
513	            num_tokens,
514	            matched_indices,
515	            postings_serialization);
516	
517	        for (size_t i = 0; i < matched_indices.size(); ++i)
518	        {
519	            String token(block_tokens.getDataAt(matched_indices[i]));
520	            auto token_info = std::make_shared<TokenPostingsInfo>(std::move(token_infos[i]));
521	
522	            postings_to_read += !(token_info->header & PostingsSerialization::Flags::EmbeddedPostings);
523	            pattern_tokens.emplace(std::move(token), std::move(token_info));
524	        }
525	
526	        if (postings_to_read >= max_postings_to_read)
527	        {
528	            /// Too many large-posting tokens matched.
529	            /// Not all dictionary blocks were scanned, so the set of matched pattern tokens is incomplete.
530	            pattern_tokens.clear();
531	            ProfileEvents::increment(ProfileEvents::TextIndexDiscardPatternScan);
532	            return;

